function updateUI(){const h=Math.ceil(player.hp);$('healthFill').style.width=h/10+'%';$('healthText').textContent=h+' / 1000';$('touchHealthFill').style.width=h/10+'%';$('touchHealthText').textContent=h+' / 1000';document.body.classList.toggle('cast-cooldown',castTimer>0);$('kills').textContent=player.kills;$('deaths').textContent=player.deaths;$('blueScore').textContent=scores[0];$('redScore').textContent=scores[1];$('clock').textContent=String(Math.floor(time/60)).padStart(2,'0')+':'+String(Math.floor(time%60)).padStart(2,'0');const states=[];if(player.wet>time)states.push('Намокание');if(player.burning>time)states.push('Горение');if(player.frozen>time)states.push('Заморозка');else if(player.chill>15)states.push('Охлаждение');if(player.ward>time)states.push('Защита');$('statuses').textContent=states.join(' · ')||'Все стихии доступны';if(player.dead)$('respawnTime').textContent=Math.max(0,Math.ceil(player.respawn-time));const count=shrines.filter(s=>s.owner===player.team).length;$('objectiveState').textContent=count+' / 2';$('objectiveText').textContent=count===2?'Святилища усиливают ваш орден':count===1?'Удерживайте захваченное святилище':'Захватите святилища';Array.from($('teamStrip').children).forEach((e,i)=>{e.style.opacity=agents[i].dead?'.25':'1';});drawMini();}
function update(dt){time+=dt;castTimer=Math.max(0,castTimer-dt);if(showMessageUntil<time)$('message').classList.remove('visible');if(touch.aiming){const direction=screenToWorld(touch.aim.x,touch.aim.y);const length=Math.hypot(direction.x,direction.z)||1;mouse={x:player.x+direction.x/length*15,z:player.z+direction.z/length*15};}if(touch.action)playerCast(touch.action);else if(touch.aiming)playerCast('forward');else if(rightHeld)playerCast();
 for(const a of agents){if(a.dead){if(time>=a.respawn){a.dead=false;a.hp=1000;a.x=a.team===0?-48:48;a.z=a.lane;a.wet=0;a.burning=0;a.chill=0;a.frozen=0;a.ward=0;a.target=null;a.g.visible=true;if(a===player)$('respawn').classList.add('hidden');}else continue;}
  if(a.burning>time){a.hp=Math.max(0,a.hp-18*dt);if(rng()<dt*8)burst(a.x,a.z,'#ed9c4f',1,.7);if(a.hp<=0){die(a,a.lastHit);continue;}}a.chill=Math.max(0,a.chill-dt*7);if(a.bot)botUpdate(a,dt);else if(a===player&&Math.hypot(touch.move.x,touch.move.y)>.01){const direction=screenToWorld(touch.move.x,touch.move.y);moveAgent(a,a.x+direction.x*5,a.z+direction.z*5,dt*Math.hypot(touch.move.x,touch.move.y));}else if(net.role==='host'&&a.id===8&&Math.hypot(net.remotePad.x,net.remotePad.y)>.01){const direction=screenToWorld(net.remotePad.x,net.remotePad.y);moveAgent(a,a.x+direction.x*5,a.z+direction.z*5,dt*Math.hypot(net.remotePad.x,net.remotePad.y));}else if(a.target){moveAgent(a,a.target.x,a.target.z,dt);if(dist(a,a.target)<.5){a.target=null;if(a===player)selection.visible=false;}}
  a.g.position.set(a.x,.035+Math.sin(time*2+a.id)*.015,a.z);a.bar.group.quaternion.copy(camera.quaternion);a.bar.fill.scale.x=a.hp/a.maxHp;a.bar.fill.position.x=-(1-a.hp/a.maxHp)*a.bar.width/2;
  a.marker.material.color.set(a.frozen>time?'#b6ebed':a.ward>time?'#e3ce7f':a===player?'#e6d599':teamColors[a.team]);a.marker.scale.setScalar(a.ward>time?1.5:1);if(a.wet>time&&rng()<dt*4)burst(a.x,a.z,'#7acbdf',1,.5);
 }
 for(let i=projectiles.length-1;i>=0;i--){const p=projectiles[i];p.life-=dt;const old={x:p.x,z:p.z};p.x+=p.dir.x*p.speed*dt;p.z+=p.dir.z*p.speed*dt;p.m.position.set(p.x,1.5+Math.sin((1.8-p.life)*2)*.35,p.z);p.m.rotation.x+=dt*4;p.m.rotation.z+=dt*3;let hit=false;for(const b of agents)if(!b.dead&&b.team!==p.a.team&&dist(b,p)<1.3){hurt(b,p.spell.damage,p.a);hit=true;break;}if(!hit)for(const s of structures)if(!s.dead&&s.team!==p.a.team&&dist(s,p)<(s.core?4:2.5)){damageStructure(s,90+p.spell.power*20,p.a);hit=true;break;}if(!hit)for(const w of walls)if(w.team!==p.a.team&&dist(w,p)<2.6){w.hp-=70;hit=true;break;}if(hit||p.life<=0){if(hit){burst(p.x,p.z,p.spell.color,10);pulse(p.x,p.z,p.spell.color,1.5);}scene.remove(p.m);p.m.geometry.dispose();projectiles.splice(i,1);}else if(rng()<.25)effectLine(old,p,p.spell.color,.06,.15);}
 for(const s of structures){if(s.dead)continue;s.crystal.rotation.y+=dt*.5;s.crystal.position.y=(s.core?5.2:4.8)+Math.sin(time*1.5)*.15;s.bar.group.quaternion.copy(camera.quaternion);s.bar.fill.scale.x=s.hp/s.maxHp;s.bar.fill.position.x=-(1-s.hp/s.maxHp)*s.bar.width/2;s.cd-=dt;if(!s.core&&s.cd<=0){const b=agents.filter(a=>!a.dead&&a.team!==s.team&&dist(a,s)<15).sort((a,b)=>dist(a,s)-dist(b,s))[0];if(b){effectLine({x:s.x,z:s.z,y:5},b,teamColors[s.team],.08,.3);hurt(b,{arcane:65},null);s.cd=1.2;}}}
 for(const s of shrines){s.gem.rotation.y+=dt;s.gem.position.y=2.5+Math.sin(time*1.6)*.3;const near=agents.filter(a=>!a.dead&&dist(a,s)<6),blue=near.filter(a=>a.team===0).length,red=near.length-blue;if(blue&&!red)s.progress=Math.min(6,s.progress+dt);if(red&&!blue)s.progress=Math.max(-6,s.progress-dt);let owner=s.progress>=6?0:s.progress<=-6?1:s.owner;if(owner!==s.owner){s.owner=owner;const color=teamColors[owner];s.gem.material=mat(color,{emissive:color,emissiveIntensity:.8});s.r.material.color.set(color);s.aura.material.color.set(color);notify(owner===0?'Ваш орден захватил святилище':'Ковен захватил святилище');}if(s.owner>=0)for(const a of near)if(a.team===s.owner)a.hp=Math.min(a.maxHp,a.hp+dt*12);}
 for(let i=walls.length-1;i>=0;i--){const w=walls[i];w.life-=dt;if(w.life<=0||w.hp<=0){burst(w.x,w.z,'#d4c99c',7);scene.remove(w.g);w.g.traverse(o=>{if(o.isMesh)o.geometry.dispose();});walls.splice(i,1);}}
}
function visualUpdate(dt){for(let i=fx.length-1;i>=0;i--){const f=fx[i];f.life-=dt;if(f.life<=0){scene.remove(f.m);f.m.geometry.dispose();if(f.m.material.isMeshBasicMaterial)f.m.material.dispose();fx.splice(i,1);continue;}if(f.type==='particle'){f.m.position.x+=f.vx*dt;f.m.position.z+=f.vz*dt;f.m.position.y+=f.vy*dt;f.vy-=dt*6;f.m.scale.setScalar(Math.max(.05,f.life/f.max));}else if(f.type==='ring'){f.m.scale.setScalar(1+(1-f.life/f.max)*f.radius);f.m.material.opacity=f.life/f.max*.8;}else f.m.material.opacity=f.life/f.max;}
 for(let i=floaters.length-1;i>=0;i--){const f=floaters[i];f.life-=dt;if(f.life<=0){f.d.remove();floaters.splice(i,1);continue;}const v=new THREE.Vector3(f.x,4+(1.1-f.life)*2,f.z).project(camera);f.d.style.left=(v.x*.5+.5)*innerWidth+'px';f.d.style.top=(-v.y*.5+.5)*innerHeight+'px';f.d.style.opacity=Math.min(1,f.life*2);}
 for(const l of waterLines){l.position.z+=dt*.6;if(l.position.z>44)l.position.z=-44;}selection.rotation.z+=dt;}
let accumulator=0;
function guestUpdate(dt,now){castTimer=Math.max(0,castTimer-dt);if(showMessageUntil<time)$('message').classList.remove('visible');if(touch.aiming){const direction=screenToWorld(touch.aim.x,touch.aim.y);mouse={x:player.x+direction.x*15,z:player.z+direction.z*15};}if(touch.action)playerCast(touch.action);else if(touch.aiming)playerCast('forward');else if(rightHeld)playerCast();if(now-net.lastInput>=100){sendNet({type:'input',input:{kind:'pad',x:touch.move.x,y:touch.move.y}});net.lastInput=now;}}
function frame(now){requestAnimationFrame(frame);const elapsed=Math.max(0,Math.min((now-last)/1000,.2)),dt=Math.min(elapsed,.05);last=now;const active=playing&&!paused&&!ended&&(net.mode==='match'||!$('help').open);if(active){if(net.role==='guest')guestUpdate(dt,now);else{accumulator+=elapsed;while(accumulator>=1/60){update(1/60);accumulator-=1/60;}if(net.role==='host'){net.remoteCastTimer=Math.max(0,net.remoteCastTimer-elapsed);if(now-net.lastState>=100){sendState();net.lastState=now;}}}visualUpdate(dt);}else accumulator=0;if(playing&&!player.dead)cameraTarget.lerp(new THREE.Vector3(player.x,0,player.z),1-Math.exp(-dt*2.5));else if(!playing)cameraTarget.lerp(new THREE.Vector3(-3,0,0),.01);camera.position.set(cameraTarget.x+43,70,cameraTarget.z+51);camera.lookAt(cameraTarget.x,0,cameraTarget.z);renderer.render(scene,camera);uiTimer+=dt;if(uiTimer>.1){uiTimer=0;updateUI();}}
window.riftbound={snapshot:()=>({agents:agents.length,teams:[agents.filter(a=>a.team===0).length,agents.filter(a=>a.team===1).length],playing,paused,queue:[...queue],hp:player.hp,position:{x:player.x,z:player.z},peerPosition:net.mode==='match'?{x:agents[net.role==='host'?8:0].x,z:agents[net.role==='host'?8:0].z}:null,net:{mode:net.mode,role:net.role,nick:net.nick,peer:net.peer,remoteCastCount:net.remoteCastCount},touch:{move:{...touch.move},aiming:touch.aiming,action:touch.action},lastPlayerCast,playerCastCount,structures:structures.length,shrines:shrines.length,time,renderer:renderer.info.render})};
requestAnimationFrame(frame);
